changeSet.sql:
ALTER TABLE clinlims.qc_control_lot
ADD CONSTRAINT chk_qc_control_lot_frequency_type
CHECK (qc_frequency_type IS NULL OR qc_frequency_type IN ('DAILY', 'PER_SHIFT', 'CUSTOM_HOURS'));
ALTER TABLE clinlims.qc_control_lot
ADD CONSTRAINT chk_qc_control_lot_frequency_hours
CHECK (qc_frequency_hours IS NULL OR qc_frequency_hours BETWEEN 1 AND 720);

ALTER TABLE clinlims.qc_result
ADD CONSTRAINT chk_qc_result_entry_point
CHECK (entry_point IS NULL OR entry_point IN ('ANALYZER_IMPORT', 'ANALYZER_LIST'));

rollback.sql:
ALTER TABLE clinlims.qc_result DROP CONSTRAINT chk_qc_result_source_shape;
ALTER TABLE clinlims.qc_result
ADD CONSTRAINT chk_qc_result_source_shape
CHECK (
    (source IN ('RDT', 'ASTM') AND result_value IS NULL AND qualitative_outcome IS NOT NULL)
    OR
    (source <> 'RDT' AND result_value IS NOT NULL)
);
